CR="/c/Users/User/AppData/Local/Temp/cleanroom-uF5m4r"; SP="/c/Users/User/AppData/Local/Temp/claude/e8f7af93dfee08eb/208de43b-f1de-439e-8f9c-4711be235a1c/scratchpad"; mkdir -p "$SP/logs"
cat > "$SP/run.ps1" <<'EOF'
$ErrorActionPreference = 'Continue'
Set-Location 'C:\Users\User\AppData\Local\Temp\cleanroom-uF5m4r'
$logs = 'C:\Users\User\AppData\Local\Temp\claude\e8f7af93dfee08eb\208de43b-f1de-439e-8f9c-4711be235a1c\scratchpad\logs'
$results = @()
function Invoke-Step([string]$name, [scriptblock]$sb) {
  $sw = [Diagnostics.Stopwatch]::StartNew()
  $global:LASTEXITCODE = 0
  $ok = $true
  try { & $sb *> (Join-Path $logs ("$($script:i).log")) } catch { $ok = $false; $_ | Out-String | Add-Content (Join-Path $logs ("$($script:i).log")) }
  $sw.Stop()
  $code = $LASTEXITCODE; if (-not $ok -and $code -eq 0) { $code = 'EXC' }
  "STEP $($script:i)`t$code`t$([math]::Round($sw.Elapsed.TotalSeconds,1))`t$name"
  $script:i++
}
$script:i = 1
Invoke-Step 'py -3.13 -m venv .venv' { py -3.13 -m venv .venv }
Invoke-Step '.venv\Scripts\Activate.ps1' { . .venv\Scripts\Activate.ps1 }
. .venv\Scripts\Activate.ps1
"PYTHON=" + (Get-Command python).Source
Invoke-Step 'python -m pip install -r requirements-dev.txt' { python -m pip install -r requirements-dev.txt }
Invoke-Step 'python -m pip install -e .' { python -m pip install -e . }
Invoke-Step 'run-scenarios' { python -m support_agent run-scenarios }
Invoke-Step 'run-scenarios --json' { python -m support_agent run-scenarios --json }
Invoke-Step 'run-scenarios --report docs/eval-report.md' { python -m support_agent run-scenarios --report docs/eval-report.md }
Invoke-Step 'ask ORD-100' { python -m support_agent ask --customer CUST-001 --message "Where is order ORD-100?" }
Invoke-Step 'ask refund + yes (bash line continuation \ as written)' { python -m support_agent ask --customer CUST-001 \
  --message "One of the wine glasses in order ORD-200 arrived broken. Can I get a refund for it?" \
  --message "yes" }
Invoke-Step 'ask refund + yes (joined on one line)' { python -m support_agent ask --customer CUST-001 --message "One of the wine glasses in order ORD-200 arrived broken. Can I get a refund for it?" --message "yes" }
Set-Content -Path messages.txt -Value 'Where is order ORD-100?' -Encoding utf8
Invoke-Step 'ask --message-file messages.txt' { python -m support_agent ask --customer CUST-001 --message-file messages.txt }
Invoke-Step 'python -m pytest' { python -m pytest }
Invoke-Step 'python -m scripts.check' { python -m scripts.check }
EOF
date +%s

